"""Create a local five-image comparison and verified delivery archive."""
from pathlib import Path
import json,html,zipfile,hashlib
H=Path(__file__).resolve().parent;r=json.loads((H/'Screening.json').read_text());variants=r['variants']
out=['<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fünf Motoranschlüsse · Leichtbauvergleich</title>',
'<style>*{box-sizing:border-box}body{margin:0;background:#eef2f4;color:#18394a;font:16px/1.5 system-ui}header,main,footer{max-width:1400px;margin:auto;padding:24px}h1{margin:0 0 12px}nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}button,a.button{font:inherit;border:1px solid #9cb2bf;border-radius:6px;padding:8px 14px;background:white;color:#18394a;cursor:pointer}button[aria-pressed=true]{background:#18394a;color:white}section{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}article{background:white;padding:16px;border-radius:8px}article[hidden]{display:none}article img{width:100%;height:auto;display:block}article h2{margin:0 0 8px;font-size:21px}article p{margin:10px 0}.note{padding:16px;border-left:4px solid #ae883c;background:#fff8eb}a{color:#096c91}.mass{font-weight:700}table{border-collapse:collapse;width:100%;margin:20px 0}td,th{text-align:left;padding:10px;border-bottom:1px solid #ccd8df}footer{color:#45606f}@media(max-width:800px){section{grid-template-columns:1fr}header,main,footer{padding:16px}}@media print{nav{display:none}section{display:block}article{break-inside:avoid}}</style>',
'<header><h1>Fünf direkte Motoranschlüsse mit Carbonrohren</h1><p>Einrohrarm zuerst prüfen. Zwei, drei oder vier Rohre ergänzen, wenn Tragfähigkeit und Steifigkeit es verlangen. Alle Varianten verwenden integrierte Aluminium-Anschlussknoten am Rahmen und am feststehenden Motorfuß.</p><p class="note"><strong>Gestaltungsstudie.</strong> Bilder sind nicht maßstäblich. Festigkeit, Knotenmasse und Montage sind noch nicht geschlossen. V1 verwendet Ø35/32 mm als neuen Vergleichsquerschnitt; V2–V5 den vorhandenen Ø20/17-mm-Querschnitt.</p><nav><button data-view="all" aria-pressed="true">Alle fünf</button>']
for v in variants:out.append(f'<button data-view="{v["id"]}" aria-pressed="false">{v["id"]} · {v["count"]} Rohr'+('e' if v['count']>1 else '')+'</button>')
out+=['</nav></header><main><section id="cards">']
for v in variants:
    out.append(f'<article id="{v["id"]}"><h2>{v["id"]} · {html.escape(v["title"])}</h2><a href="{v["id"]}.png"><img src="{v["id"]}.png" alt="{html.escape(v["title"])} mit {v["count"]} Carbonrohren" width="1536" height="1024"></a><p>{html.escape(v["purpose"])}</p><p class="mass">Nur Rohrmasse je Arm: ca. {v["tube_mass_assumed_kg"]*1000:.0f} g</p><p>{html.escape(v["risk"])}</p></article>')
out+=['</section><h2>Überschlag zum Einzelrohr</h2><p>Angenommener Vergleich: 400 N Querlast, 420 mm idealisierter Kragarm, 20 Nm Torsion; Biegemodul 70 GPa, Schubmodul 5 GPa. Keine Sicherheitsfaktoren und keine geprüften Laminatwerte.</p><table><thead><tr><th>Einzelrohr</th><th>Durchbiegung</th><th>Verdrehung</th><th>Biegespannung</th></tr></thead><tbody>']
for c in r['single_tube_comparison']:out.append(f'<tr><td>Ø{c["od_mm"]}/{c["id_mm"]} mm</td><td>{c["tip_deflection_mm"]:.1f} mm</td><td>{c["twist_deg"]:.1f}°</td><td>{c["bending_stress_MPa"]:.0f} MPa</td></tr>')
out+=['</tbody></table><p class="note">Die Rohrmasse umfasst keine Knoten, Klemmkappen, Schrauben oder Isolierlagen. Eine Rangfolge nach <strong>Gesamtgewicht</strong> ist noch nicht belegt. Der alte separate Motorträger wiegt rund 502 g je Motor; sein Wegfall ist eine Brutto-Entnahme, von der die Masse neuer Knoten abgezogen werden muss.</p></main><footer><a href="README.md">Annahmen und Grenzen</a> · <a href="Screening.json">Rechenergebnisse</a> · <a href="Motoranschluss_5_Varianten.zip">Fünf Bilder und Rechenunterlagen herunterladen</a><p>Motor-Bauraumreferenz; Anschlussbild aus alter Projektzeichnung, nicht OEM-bestätigt. Die Bilder ersetzen keine Montagezeichnung. Der bestehende D06-Rotorfreiraumkonflikt wird durch diese Studie nicht als gelöst nachgewiesen.</p></footer><script>for(const b of document.querySelectorAll("[data-view]"))b.onclick=()=>{for(const q of document.querySelectorAll("[data-view]"))q.setAttribute("aria-pressed",q===b?"true":"false");const v=b.dataset.view;for(const a of document.querySelectorAll("article"))a.hidden=v!=="all"&&a.id!==v;document.querySelector("section").style.gridTemplateColumns=v==="all"?"":"1fr";};</script></html>']
(H/'Vergleich.html').write_text(''.join(out))
files=sorted(p for p in H.iterdir() if p.is_file() and p.suffix not in ['.zip','.b64'] and p.name!='SHA256SUMS.txt')
manifest=''.join(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+p.name+'\n' for p in files);(H/'SHA256SUMS.txt').write_text(manifest)
with zipfile.ZipFile(H/'Motoranschluss_5_Varianten.zip','w',zipfile.ZIP_DEFLATED) as z:
    for p in files:z.write(p,p.name)
    z.writestr('SHA256SUMS.txt',manifest)
with zipfile.ZipFile(H/'Motoranschluss_5_Varianten.zip') as z:assert z.testzip() is None
assert len(list(H.glob('V?.png')))==5 and [v['count'] for v in variants]==[1,2,2,3,4]
print('Five independent images and comparison archive verified')
